-- Local admin password rotation (docs/design/local-admin.md): one managed local account per
-- device, its password generated by the server, stored in the client's vault (a managed item of
-- kind `local_admin`, state `pending` until the agent confirms) before the agent sets it.

CREATE TABLE local_admin_state (
    agent_id        uuid PRIMARY KEY REFERENCES agents(id) ON DELETE CASCADE,
    account         text NOT NULL,
    vault_item_id   uuid REFERENCES vault_items(id) ON DELETE SET NULL,
    status          text NOT NULL CHECK (status IN ('ok', 'pending', 'failed', 'unsupported', 'conflict')),
    rotated_at      timestamptz,
    next_rotate_at  timestamptz,
    -- What started the rotation in progress or the last one: first, schedule, reveal, manual.
    rotate_reason   text CHECK (rotate_reason IN ('first', 'schedule', 'reveal', 'manual')),
    -- Sends of the pending password so far (reset when one succeeds).
    attempts        integer NOT NULL DEFAULT 0,
    -- The set in flight: only its reply is accepted.
    request_id      uuid,
    sent_at         timestamptz,
    last_error      text,
    updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON local_admin_state (next_rotate_at);

-- The `local_admin` policy module: single-instance, in All devices, off until a set turns it on.
-- The module list is 0038's plus this one.
ALTER TABLE policy_items DROP CONSTRAINT IF EXISTS policy_items_module_check;
ALTER TABLE policy_items ADD CONSTRAINT policy_items_module_check
    CHECK (module IN ('alert', 'schedule', 'patch', 'security', 'remote_access', 'agent', 'software', 'automation', 'disk_encryption', 'local_admin'));
CREATE UNIQUE INDEX policy_items_single_local_admin ON policy_items (module) WHERE module = 'local_admin';

